import sys; sys.path.insert(0, '_tools'); from spec import enrich
enrich('la-luz', 'C',
 [dict(t=364, e=428, titulo='Tiempos difíciles: días de debilitamiento', txt='Y dice: «Debes saber esto». Dígale al hermano que está a la puerta suya: «Debes saber esto». Es decir, no nos da margen la Biblia para no saberlo. Tenemos que saberlo. Y entonces dice: «Debes saber esto: que en los últimos días vendrán tiempos difíciles». Y hemos dicho que esa palabra «difícil» es la palabra en el griego jalepos o chalepos, que lo que representa es días de debilitamiento. Es decir, en base a la noticia de todo lo que va a estar sucediendo, en base a la atmósfera contaminante que va a estar sucediendo en los tiempos finales, mucha población se va a debilitar…'),
  dict(t=606, e=670, titulo='Tinieblas para la tierra, luz para nosotros', txt='Acuérdese que estoy relacionando todo esto al tiempo final, que es un tiempo difícil, porque tinieblas cubrirán la tierra […] y densa oscuridad a los pueblos; pero sobre ti amanecerá el Señor y sobre ti aparecerá su gloria. Entonces, esto me lleva a la consideración de algo que va a tener que ver con el tiempo que nos tocó vivir, porque por un lado, en el mundo, se van a vivir esos oscurecimientos; por el otro lado, Dios tiene siempre una salida. Mire, eso es increíble: cuando había plaga y enfermedad para Egipto, para el pueblo de Dios había protección y sanidad. Cuando había escasez en Egipto, para el pueblo de Dios había abundancia. Donde abundó el pecado, sobreabunda la gracia. Pero acá está diciendo que va a venir tinieblas sobre la tierra, pero a nosotros, luz.'),
  dict(t=3968, e=4030, titulo='Interesémonos en ver cómo ayudamos', txt='Pero sí, cuando usted se entera de un hermano en alguna necesidad, decir: «Yo lo voy a ayudar». El hermano está pasando problemas económicos: «Le voy a llevar un cartón de huevos, unos panes, una leche, y lo bendigo». Y luego, después de usted, va a llegar otro que también lo va a bendecir, y luego otro. Imagínese, hermano, alguien que tiene necesidad y que todos sus hermanos lo van acompañando y bendiciendo. ¿Cómo se siente? Pero eso, ¿quién lo va a hacer? Sino alguien, hermano, que quiere crecer en la luz. Mire, regularmente el pensamiento de la gente no es ayudar, sino que le ayuden. Quiere la ayuda, pero no quiere ayudar. No es eso lo que estoy hablando yo. Lo que yo estoy hablando es: interesémonos en ver cómo ayudamos. Fíjese que por eso es que decimos que el tiempo final va a ser un tiempo espantoso para el mundo, pero glorioso para la iglesia de Cristo. Es decir, tenemos que ir nosotros como en contracorriente de todo lo malo que está pasando allí afuera.')],
 [dict(t=768, txt='Algunos quieren ser luz donde hay luz, pero nosotros somos llamados a ser luz en medio de tiniebla.'),
  dict(t=1779, txt='La palabra profética más segura es la lámpara: es la Biblia, es el mensaje, el texto escrito que nos da dirección y nos dice hacia dónde ir.'),
  dict(t=4311, txt='Nosotros queremos ser luz, Señor, siendo, actuando, viviendo de forma diferente, no pensando en nuestra necesidad o nuestro interés, sino ayudando.')],
 ['¿En qué lugar de tu semana (el trabajo, la familia, los estudios) te toca ser luz precisamente donde hay tiniebla? ¿Cómo se vería eso en la práctica?',
  '¿Cuándo fue la última vez que te interesaste de verdad por la necesidad de un hermano? ¿Qué podrías hacer esta semana?',
  '¿Qué lugar tiene hoy la Palabra escrita, como lámpara, para decirte hacia dónde ir?'])
